        "script": "const approved = $vars.managerReview1.output.approved;\nconst rejectionReason = $vars.managerReview1.output.rejectionreason;\nconst expenseId = $vars.fetchExpense1.output.expenseId;\nconst submitter = $vars.fetchExpense1.output.submitter;\nconst amount = $vars.fetchExpense1.output.amount;\n\nif (approved) {\n  return {\n    status: \"APPROVED\",\n    message: \"Expense \" + expenseId + \" submitted by \" + submitter + \" for $\" + amount + \" has been APPROVED.\"\n  };\n} else {\n  return {\n    status: \"REJECTED\",\n    message: \"Expense \" + expenseId + \" submitted by \" + submitter + \" for $\" + amount + \" has been REJECTED. Reason: \" + (rejectionReason || \"No reason provided.\")\n  };\n}"
      },
      "outputs": {
        "output": {
          "type": "object",
          "description": "The return value of the script",
          "source": "=result.response",
          "var": "output"
        },
        "error": {
          "type": "object",
          "description": "Error information if the script fails",
          "source": "=result.Error",
          "var": "error"
        }
      }
    },
